code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r, c) in seen: continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == v:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells) >= 3:
                boxes.append((v, min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    # Keep substantial colored objects; discard scattered defects, then fill their rectangular bounds.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg: out[r][c] = bg
    for v, r0, r1, c0, c1 in boxes:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1): out[r][c] = v
    return out
'''
